    private static func dynamic(light l: (Double, Double, Double, Double), dark d: (Double, Double, Double, Double)) -> Color {
        #if os(watchOS)
        return Color(.sRGB, red: d.0, green: d.1, blue: d.2, opacity: d.3)
        #elseif canImport(UIKit)
        return Color(uiColor: UIColor { traits in
            let c = traits.userInterfaceStyle == .dark ? d : l
            return UIColor(red: c.0, green: c.1, blue: c.2, alpha: c.3)
        })
        #elseif canImport(AppKit)
        return Color(nsColor: NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua, .vibrantDark, .vibrantLight]).map { $0 == .darkAqua || $0 == .vibrantDark } ?? false
            let c = isDark ? d : l
            return NSColor(srgbRed: c.0, green: c.1, blue: c.2, alpha: c.3)
        })
        #else
        return Color(.sRGB, red: l.0, green: l.1, blue: l.2, opacity: l.3)
        #endif
    }

    public enum Platform: String, CaseIterable, Sendable { case iOS, iPadOS, macOS, tvOS, watchOS }

    /// The platform this code is running on (iPad and Mac Catalyst resolved at runtime).
    @MainActor public static var currentPlatform: Platform {
        #if os(tvOS)
        return .tvOS
        #elseif os(watchOS)
        return .watchOS
        #elseif os(macOS)
        return .macOS
        #elseif os(visionOS)
        return .iPadOS
        #else
        switch UIDevice.current.userInterfaceIdiom {
        case .pad: return .iPadOS
        case .mac: return .macOS
        default: return .iOS
        }
        #endif
    }

    /// Platform metrics (docs/APPLE_PLATFORMS.md). Lengths are points; `motion` is seconds.
    public struct Metrics: Sendable {
        /// Smallest hit target (pointer target on macOS).
        public let tapMin: CGFloat
        /// Standard button, field and segment height.
        public let controlHeight: CGFloat
        /// Horizontal content margin from the screen edge (tvOS: includes the overscan safe area).
        public let gutter: CGFloat
        /// Minimum top inset the app adds itself; iOS/iPadOS system insets come from env(safe-area-inset-top).
        public let safeTop: CGFloat
        /// Minimum bottom inset the app adds itself; add env(safe-area-inset-bottom) for the home indicator.
        public let safeBottom: CGFloat
        /// Minimum side inset for anything that isn't a full-bleed background.
        public let safeSide: CGFloat
        /// Navigation bar, toolbar or title area height.
        public let barHeight: CGFloat
        /// Tab bar height (bottom on iPhone, top on iPad and TV); 0 = sidebar instead.
        public let tabbarHeight: CGFloat
        /// Sidebar / source list column width; 0 = none.
        public let sidebarWidth: CGFloat
        /// Readable measure for text columns.
        public let contentMax: CGFloat
        /// Body text size at the default Dynamic Type size; every type style scales by body-size / the theme's body.
        public let bodySize: CGFloat
        /// Multiplier on the theme's spacing tokens.
        public let spaceScale: Double
        /// Multiplier on the theme's radius tokens (0 stays 0).
        public let radiusScale: Double
        /// Bar and list icon size.
        public let iconSize: CGFloat
        /// Growth of the focused element (tvOS focus engine); 1 = none.
        public let focusScale: Double
        /// Keyboard focus ring width; 0 = focus is shown another way.
        public let focusRingWidth: CGFloat
        /// Backdrop blur behind material; 0 = the theme's material is opaque by design.
        public let materialBlur: CGFloat
        /// Base transition duration for focus moves and bar changes.
        public let motion: Double
        /// Pointer hover growth for cards (iPadOS pointer); 1 = none.
        public let hoverScale: Double
        /// Smallest text allowed on this platform (captions, legal).
        public let minText: CGFloat
    }

